<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { Activity, Bell, BookOpen, CalendarDays, Check, ChevronDown, CircleHelp, Clock3, CloudDownload, Flame, Flower2, Goal, LayoutDashboard, ListChecks, LogOut, Menu, Moon, Plus, Search, Settings, ShieldCheck, Sparkles, Sprout, Target, Trophy, UserRound, Waves, X, ChartNoAxesCombined } from 'lucide-vue-next'
import { request, api } from './api'
type Habit={id:number;name:string;category:string;color:string;icon:string;frequency:string;entries?:{status:string;entry_date:string}[]}
type GoalItem={id:number;title:string;progress:number;status:string;priority:string}
type Task={id:number;title:string;status:string;priority:string}
const nav=[{label:'داشبورد',icon:LayoutDashboard},{label:'عادت‌ها',icon:Sprout},{label:'تقویم',icon:CalendarDays},{label:'اهداف',icon:Target},{label:'وظایف',icon:ListChecks},{label:'تایمر تمرکز',icon:Clock3},{label:'آمار و تحلیل',icon:ChartNoAxesCombined},{label:'جوایز و دستاوردها',icon:Trophy},{label:'مربی هوشمند',icon:Sparkles},{label:'اعلان‌ها',icon:Bell},{label:'پروفایل',icon:UserRound},{label:'تنظیمات',icon:Settings},{label:'پشتیبان‌گیری',icon:CloudDownload}]
const active=ref('داشبورد'), sidebarOpen=ref(false), loading=ref(false), error=ref(''), toast=ref('')
const habits=ref<Habit[]>([]), goals=ref<GoalItem[]>([]), tasks=ref<Task[]>([])
const stats=ref<any>({habits:{active:0,completed:0,completion_rate:0},tasks:{pending:0},goals:{active:0},focus:{minutes_today:0,sessions_today:0}})
const coachItems=ref<any[]>([]), coachSummary=ref<any>({}), notifications=ref<any[]>([]), settings=ref<any>({theme:'dark',locale:'fa',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,day_start_hour:4,accent_color:'#8b7cff',notification_preferences:{habit_reminders:true,daily_summary:true,weekly_summary:true,task_deadlines:true}}), analytics=ref<any>(null), rewardData=ref<any>({summary:{xp_total:0,level:1,progress_percent:0},badges:[],events:[]})
const settingsSaving=ref(false), reportFrom=ref(localDate(new Date(Date.now()-29*86400000))), reportTo=ref(localDate())
const showHabitForm=ref(false), habitName=ref(''), habitCategory=ref('رشد فردی'), search=ref(''), isDemo=ref(false)
const token=ref(sessionStorage.getItem('habittrack_token')||''), loginEmail=ref('demo@habittrack.local'), loginPassword=ref('HabitTrackDemo!234')
const authMode=ref<'login'|'register'>('login'), registerName=ref(''), registerPasswordConfirm=ref('')
const showGoalForm=ref(false), goalTitle=ref(''), goalPriority=ref('medium')
const showTaskForm=ref(false), taskTitle=ref(''), taskPriority=ref('medium')
const focusMinutes=ref(25), timerSeconds=ref(1500), timerRunning=ref(false), focusSessionId=ref<number|null>(null)
let timerInterval: ReturnType<typeof setInterval>|null=null

// Local calendar date as YYYY-MM-DD. toISOString() returns the UTC date, which is the
// previous day for users in Tehran between 00:00 and 03:30, so it must not be used for entry dates.
function localDate(d:Date=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const currentUser=ref<{name:string;email:string}|null>(null)
const displayName=computed(()=>isDemo.value?'حساب نمایشی':(currentUser.value?.name||'کاربر'))
const firstName=computed(()=>displayName.value.trim().split(/\s+/)[0]||'کاربر')
const displayInitial=computed(()=>displayName.value.trim().charAt(0)||'م')
const isAuthenticated=computed(()=>!!token.value)
const weekMax=computed(()=>Math.max(1,...((stats.value.week||[]) as {completed:number}[]).map(d=>d.completed)))
const filteredHabits=computed(()=>habits.value.filter(h=>h.name.toLowerCase().includes(search.value.toLowerCase())))
const pageSubtitles:Record<string,string>={'داشبورد':'بهتر از دیروز؛ یک قدم کوچک در هر روز 🌿','عادت‌ها':'تداوم، از قدم‌های کوچک ساخته می‌شود.','تقویم':'نگاهی به مسیر و روزهای پربارت.','اهداف':'روی چیزهایی تمرکز کن که برایت مهم‌اند.','وظایف':'کارها را کوچک کن و یکی‌یکی جلو برو.','تایمر تمرکز':'یک کار، یک بازه، تمام توجهت.','آمار و تحلیل':'پیشرفت واقعی را با داده ببین.','جوایز و دستاوردها':'هر قدم ارزش جشن گرفتن دارد.','مربی هوشمند':'پیشنهادهای ساده بر اساس عملکردت.','اعلان‌ها':'یادآوری‌هایی که خودت انتخاب می‌کنی.','پروفایل':'مسیر رشد شخصی تو.','تنظیمات':'تجربه‌ات را مطابق نیازت تنظیم کن.','پشتیبان‌گیری':'اطلاعاتت را مدیریت و نگهداری کن.'}
function notify(s:string){toast.value=s;setTimeout(()=>toast.value='',2600)}
async function loadData(){if(!token.value)return;loading.value=true;error.value='';try{const [d,h,g,t]=await Promise.all([request<any>('get','/dashboard'),request<any>('get','/habits'),request<any>('get','/goals'),request<any>('get','/tasks')]);stats.value=d;habits.value=h.data||h;goals.value=g.data||g;tasks.value=t.data||t;currentUser.value=(await request<any>('get','/auth/me')).user;const sr=await request<any>('get','/settings');settings.value={...settings.value,...(sr.settings||{}),notification_preferences:{...settings.value.notification_preferences,...((sr.settings||{}).notification_preferences||{})}};isDemo.value=false}catch(e:any){error.value=e?.response?.data?.message||'اتصال به API برقرار نشد. سرور Laravel را اجرا کن.'}finally{loading.value=false}}
async function loadCurrentPage(){if(!token.value)return;try{if(active.value==='مربی هوشمند'){const r=await request<any>('get','/coach/recommendations');coachItems.value=r.data||[];coachSummary.value=r.summary||{}}else if(active.value==='اعلان‌ها'){const r=await request<any>('get','/notifications');notifications.value=r.data?.data||r.data||[]}else if(active.value==='تنظیمات'){const r=await request<any>('get','/settings');settings.value={...settings.value,...(r.settings||{}),notification_preferences:{...settings.value.notification_preferences,...((r.settings||{}).notification_preferences||{})}}}else if(active.value==='آمار و تحلیل'){analytics.value=await request<any>('get',`/analytics?from=${reportFrom.value}&to=${reportTo.value}`)}else if(active.value==='جوایز و دستاوردها'){rewardData.value=await request<any>('get','/rewards')}else if(active.value==='تقویم'){await loadCalendar()}}catch(e:any){notify(e?.response?.data?.message||'بارگذاری این بخش از API ناموفق بود')}}
async function decideCoach(item:any,decision:'accepted'|'rejected'){try{await request('post',`/coach/recommendations/${item.id}/decision`,{decision});await loadCurrentPage();notify(decision==='accepted'?'پیشنهاد پذیرفته شد':'پیشنهاد رد شد')}catch(e:any){notify(e?.response?.data?.message||'ثبت تصمیم ناموفق بود')}}
async function evaluateCoach(item:any){const note=prompt('نتیجه اجرای پیشنهاد را کوتاه بنویس (اختیاری):')??'';try{await request('post',`/coach/recommendations/${item.id}/evaluate`,{evaluation_note:note});await loadCurrentPage();notify('ارزیابی ثبت شد')}catch(e:any){notify(e?.response?.data?.message||'ارزیابی ناموفق بود')}}
async function markNotificationRead(n:any){try{await request('patch',`/notifications/${n.id}/read`);n.read_at=new Date().toISOString()}catch{notify('خوانده‌شدن اعلان ثبت نشد')}}
async function markAllNotificationsRead(){try{await request('post','/notifications/read-all');notifications.value.forEach(n=>n.read_at=n.read_at||new Date().toISOString());notify('همه اعلان‌ها خوانده‌شده شدند')}catch{notify('به‌روزرسانی اعلان‌ها ناموفق بود')}}
async function saveSettings(){if(!token.value||isDemo.value){notify('برای ذخیره تنظیمات واقعی وارد حساب شو');return}settingsSaving.value=true;try{const r=await request<any>('put','/settings',settings.value);settings.value={...settings.value,...r.settings};notify('تنظیمات در سرور ذخیره شد')}catch(e:any){notify(e?.response?.data?.message||'ذخیره تنظیمات ناموفق بود')}finally{settingsSaving.value=false}}
async function loadAnalytics(){if(!token.value){notify('برای مشاهده آمار واقعی وارد حساب شو');return}try{analytics.value=await request<any>('get',`/analytics?from=${reportFrom.value}&to=${reportTo.value}`)}catch(e:any){notify(e?.response?.data?.message||'دریافت آمار ناموفق بود')}}
async function downloadBackup(){if(!token.value||isDemo.value){notify('برای نسخه پشتیبان کامل وارد حساب شو');return}try{const response=await api.get('/backup/export',{responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download='habittrack-backup.json';a.click();URL.revokeObjectURL(url);notify('نسخه پشتیبان از سرور دریافت شد')}catch{notify('دریافت نسخه پشتیبان ناموفق بود')}}
async function downloadCsv(){if(!token.value){notify('برای دریافت گزارش وارد حساب شو');return}try{const response=await api.get('/reports/habits.csv',{params:{from:reportFrom.value,to:reportTo.value},responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download='habittrack-report.csv';a.click();URL.revokeObjectURL(url);notify('گزارش CSV دانلود شد')}catch{notify('ساخت گزارش ناموفق بود')}}
async function login(){try{const endpoint=authMode.value==='register'?'/auth/register':'/auth/login';const payload=authMode.value==='register'?{name:registerName.value,email:loginEmail.value,password:loginPassword.value,password_confirmation:registerPasswordConfirm.value}:{email:loginEmail.value,password:loginPassword.value};const r=await request<any>('post',endpoint,payload);token.value=r.token;sessionStorage.setItem('habittrack_token',r.token);await loadData();notify(authMode.value==='register'?'حسابت ساخته شد':'با موفقیت وارد شدی')}catch(e:any){error.value=e?.response?.data?.message||'عملیات ناموفق بود. اطلاعات را بررسی و دوباره تلاش کن.'}}
async function demo(){token.value='';isDemo.value=true;error.value='';habits.value=[{id:1,name:'مطالعه کتاب',category:'رشد فردی',color:'#a78bfa',icon:'book-open',frequency:'daily',entries:[{status:'completed',entry_date:localDate()}]},{id:2,name:'تمرین برنامه‌نویسی',category:'یادگیری',color:'#22d3ee',icon:'code',frequency:'daily',entries:[]},{id:3,name:'ورزش',category:'سلامت',color:'#fb7185',icon:'activity',frequency:'daily',entries:[]},{id:4,name:'نوشیدن آب',category:'سلامت',color:'#38bdf8',icon:'droplet',frequency:'daily',entries:[]},{id:5,name:'یادگیری زبان',category:'یادگیری',color:'#fbbf24',icon:'languages',frequency:'daily',entries:[]}];goals.value=[{id:1,title:'ساخت نمونه‌کار حرفه‌ای',progress:65,status:'active',priority:'high'},{id:2,title:'مطالعه روزانه زبان',progress:42,status:'active',priority:'medium'}];tasks.value=[{id:1,title:'برنامه امروز را مرور کن',status:'pending',priority:'medium'},{id:2,title:'روی یک قابلیت پروژه کار کن',status:'pending',priority:'high'}];stats.value={habits:{active:5,completed:1,completion_rate:20},tasks:{pending:2},goals:{active:2},focus:{minutes_today:50,sessions_today:2}};notify('حالت نمایشی فعال شد؛ برای ذخیره واقعی به API وارد شو')}
async function createHabit(){if(!habitName.value.trim())return;try{if(isDemo.value){habits.value.unshift({id:Date.now(),name:habitName.value,category:habitCategory.value,color:'#8b7cff',icon:'sprout',frequency:'daily',entries:[]})}else{await request('post','/habits',{name:habitName.value,category:habitCategory.value,frequency:'daily',color:'#8b7cff'});await loadData()}habitName.value='';showHabitForm.value=false;notify('عادت اضافه شد')}catch{notify('ذخیره عادت ناموفق بود')}}
async function editHabit(h:Habit){const name=prompt('نام جدید عادت:',h.name)?.trim();if(!name||name===h.name)return;try{if(isDemo.value)h.name=name;else{await request('put',`/habits/${h.id}`,{name});await loadData()}notify('عادت ویرایش شد')}catch{notify('ویرایش عادت ناموفق بود')}}
async function removeHabit(h:Habit){if(!confirm(`عادت «${h.name}» حذف شود؟`))return;try{if(isDemo.value)habits.value=habits.value.filter(x=>x.id!==h.id);else{await request('delete',`/habits/${h.id}`);await loadData()}notify('عادت حذف شد')}catch{notify('حذف عادت ناموفق بود')}}
async function completeHabit(h:Habit){try{if(isDemo.value){h.entries=[{status:'completed',entry_date:localDate()}]}else{await request('put',`/habits/${h.id}/entries`,{entry_date:localDate(),status:'completed',value:1});await loadData()}notify('عادت امروز ثبت شد')}catch{notify('ثبت عادت ناموفق بود')}}

async function createGoal(){if(!goalTitle.value.trim())return;try{if(isDemo.value)goals.value.unshift({id:Date.now(),title:goalTitle.value,progress:0,status:'active',priority:goalPriority.value});else{await request('post','/goals',{title:goalTitle.value,priority:goalPriority.value,status:'active',progress:0});await loadData()}goalTitle.value='';showGoalForm.value=false;notify('هدف اضافه شد')}catch{notify('ذخیره هدف ناموفق بود')}}
async function updateGoal(g:GoalItem,delta:number){const progress=Math.max(0,Math.min(100,(g.progress||0)+delta));try{if(isDemo.value)g.progress=progress;else{await request('put',`/goals/${g.id}`,{progress,status:progress===100?'completed':'active'});await loadData()}notify('پیشرفت هدف ذخیره شد')}catch{notify('به‌روزرسانی هدف ناموفق بود')}}
async function removeGoal(g:GoalItem){if(!confirm('این هدف حذف شود؟'))return;try{if(isDemo.value)goals.value=goals.value.filter(x=>x.id!==g.id);else{await request('delete',`/goals/${g.id}`);await loadData()}notify('هدف حذف شد')}catch{notify('حذف هدف ناموفق بود')}}
async function createTask(){if(!taskTitle.value.trim())return;try{if(isDemo.value)tasks.value.unshift({id:Date.now(),title:taskTitle.value,status:'pending',priority:taskPriority.value});else{await request('post','/tasks',{title:taskTitle.value,priority:taskPriority.value,status:'pending'});await loadData()}taskTitle.value='';showTaskForm.value=false;notify('وظیفه اضافه شد')}catch{notify('ذخیره وظیفه ناموفق بود')}}
async function toggleTask(t:Task){const status=t.status==='completed'?'pending':'completed';try{if(isDemo.value)t.status=status;else{await request('put',`/tasks/${t.id}`,{status});await loadData()}notify(status==='completed'?'وظیفه انجام شد':'وظیفه به فهرست برگشت')}catch{notify('به‌روزرسانی وظیفه ناموفق بود')}}
async function removeTask(t:Task){if(!confirm('این وظیفه حذف شود؟'))return;try{if(isDemo.value)tasks.value=tasks.value.filter(x=>x.id!==t.id);else{await request('delete',`/tasks/${t.id}`);await loadData()}notify('وظیفه حذف شد')}catch{notify('حذف وظیفه ناموفق بود')}}
async function startFocus(){if(timerRunning.value)return;try{if(!isDemo.value){const r=await request<any>('post','/focus-sessions',{planned_minutes:focusMinutes.value});focusSessionId.value=r.id}timerRunning.value=true;timerInterval=setInterval(()=>{if(timerSeconds.value>0)timerSeconds.value--;else finishFocus()},1000);notify('جلسه تمرکز شروع شد')}catch{notify('شروع جلسه تمرکز ناموفق بود')}}
async function finishFocus(){if(timerInterval){clearInterval(timerInterval);timerInterval=null}timerRunning.value=false;const actual=Math.max(0,Math.round((focusMinutes.value*60-timerSeconds.value)/60));try{if(focusSessionId.value&&!isDemo.value)await request('post',`/focus-sessions/${focusSessionId.value}/finish`,{actual_minutes:actual,status:timerSeconds.value===0?'completed':'cancelled'});focusSessionId.value=null;if(timerSeconds.value===0){stats.value.focus={...(stats.value.focus||{}),minutes_today:(stats.value.focus?.minutes_today||0)+actual,sessions_today:(stats.value.focus?.sessions_today||0)+1};notify('آفرین! جلسه تمرکز کامل شد')}else notify('جلسه تمرکز پایان یافت')}catch{notify('جلسه تمام شد اما ذخیره‌سازی API ناموفق بود')}}
async function resetFocus(){if(focusSessionId.value)await finishFocus();if(timerInterval){clearInterval(timerInterval);timerInterval=null}timerRunning.value=false;focusSessionId.value=null;timerSeconds.value=focusMinutes.value*60}
function setFocusMinutes(n:number){if(timerRunning.value)return;focusMinutes.value=n;timerSeconds.value=n*60}
async function logout(){try{if(token.value)await request('post','/auth/logout')}catch{}token.value='';sessionStorage.removeItem('habittrack_token');habits.value=[];goals.value=[];tasks.value=[];isDemo.value=false;currentUser.value=null}
const doneToday=(h:Habit)=>h.entries?.some(e=>e.status==='completed'&&e.entry_date.slice(0,10)===localDate())
// Month grid for the calendar page. Persian weeks start on Saturday, hence the (getDay()+1)%7 offset.
const calendarMarks=ref<Record<string,number>>({})
// Persian (Jalali) calendar via Intl. Each cell still carries its Gregorian date, which is what the API uses.
const persianFmt=new Intl.DateTimeFormat('en-u-ca-persian-nu-latn',{year:'numeric',month:'numeric',day:'numeric'})
function persianParts(d:Date){const p:Record<string,string>={};for(const x of persianFmt.formatToParts(d))p[x.type]=x.value;return {y:Number(p.year),m:Number(p.month),d:Number(p.day)}}
const calendarOffset=ref(0)
const calendarStart=computed(()=>{const today=new Date(),t=persianParts(today);let ty=t.y,tm=t.m+calendarOffset.value;while(tm>12){tm-=12;ty++}while(tm<1){tm+=12;ty--}
  let cur=new Date(today.getFullYear(),today.getMonth(),today.getDate()+Math.round(calendarOffset.value*30.4))
  for(let i=0;i<120;i++){const p=persianParts(cur);if(p.y===ty&&p.m===tm)break;const before=p.y*12+p.m<ty*12+tm;cur=new Date(cur.getFullYear(),cur.getMonth(),cur.getDate()+(before?1:-1))}
  while(persianParts(cur).d>1)cur=new Date(cur.getFullYear(),cur.getMonth(),cur.getDate()-1)
  return cur})
const calendarLabel=computed(()=>new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'long',year:'numeric'}).format(calendarStart.value))
const calendarCells=computed(()=>{const first=calendarStart.value,f=persianParts(first),lead=(first.getDay()+1)%7;const cells:({date:string;day:number}|null)[]=Array.from({length:lead},()=>null);let cur=new Date(first);for(;;){const p=persianParts(cur);if(p.m!==f.m||p.y!==f.y)break;cells.push({date:localDate(cur),day:p.d});cur=new Date(cur.getFullYear(),cur.getMonth(),cur.getDate()+1)}while(cells.length%7)cells.push(null);return cells})
// Appearance: theme and accent color are applied to the page; saved settings are re-applied whenever they change.
function applyAppearance(){const s=settings.value;const sysLight=window.matchMedia?.('(prefers-color-scheme: light)').matches;const theme=s.theme==='system'?(sysLight?'light':'dark'):(s.theme||'dark');document.documentElement.dataset.theme=theme;if(s.accent_color)document.documentElement.style.setProperty('--purple',s.accent_color)}
watch(settings,applyAppearance,{deep:true})
async function loadCalendar(){if(!token.value){calendarMarks.value={};return}const days=calendarCells.value.filter(Boolean) as {date:string}[];try{const r=await request<any>('get',`/analytics?from=${days[0].date}&to=${days[days.length-1].date}`);calendarMarks.value=Object.fromEntries((r.days||[]).map((d:{date:string;completed:number})=>[d.date,d.completed]))}catch(e:any){notify(e?.response?.data?.message||'بارگذاری تقویم ناموفق بود')}}
function shiftCalendar(n:number){calendarOffset.value+=n;loadCalendar()}
onMounted(()=>{applyAppearance();loadData()})
watch(active,()=>loadCurrentPage())
watch(token,()=>loadCurrentPage())
onUnmounted(()=>{if(timerInterval)clearInterval(timerInterval)})
</script>

<template>
<div class="app-shell">
  <aside class="sidebar" :class="{open:sidebarOpen}">
    <div class="brand"><div class="brand-mark"><Sprout :size="25"/></div><div><b>HabitTrack</b><small>عادت‌های کوچک، تغییرهای بزرگ</small></div><button class="mobile-close" @click="sidebarOpen=false"><X/></button></div>
    <div class="workspace"><div class="workspace-dot"></div><span>فضای شخصی</span><ChevronDown :size="14"/></div>
    <nav><button v-for="item in nav" :key="item.label" :class="{selected:active===item.label}" @click="active=item.label;sidebarOpen=false;loadCurrentPage()"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><span v-if="item.label==='عادت‌ها'" class="nav-count">{{habits.length}}</span></button></nav>
    <div class="sidebar-bottom"><div class="streak-card"><div class="streak-icon"><Flame :size="20"/></div><div><b>{{stats.streak_days??0}} روز استمرار</b><small>ادامه بده، عالی پیش می‌روی!</small></div><span>↗</span></div><div class="user-mini"><div class="avatar">{{displayInitial}}</div><div class="user-copy"><b>{{displayName}}</b><small>{{isDemo?'حالت نمایشی':isAuthenticated?'حساب متصل':'مهمان'}}</small></div><button title="خروج" @click="logout"><LogOut :size="17"/></button></div></div>
  </aside>
  <main class="main-area">
    <header class="topbar"><button class="icon-btn mobile-menu" @click="sidebarOpen=true"><Menu/></button><div class="crumb">فضای شخصی <span>/</span> <b>{{active}}</b></div><div class="top-actions"><label class="search-box"><Search :size="17"/><input v-model="search" placeholder="جست‌وجوی عادت‌ها..."/></label><button class="icon-btn" title="اعلان‌ها" @click="active='اعلان‌ها'"><Bell :size="18"/><i></i></button><button class="profile-pill" @click="active='پروفایل'"><div class="avatar small">{{displayInitial}}</div><span>{{firstName}}</span><ChevronDown :size="14"/></button></div></header>
    <section v-if="!isAuthenticated&&!isDemo" class="welcome-login">
      <div class="login-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><Sprout :size="58"/><h1>عادت‌های کوچک،<br/><span>تغییرهای بزرگ.</span></h1><p>هر روز فقط یک قدم بهتر شو. مسیر پیشرفتت را ببین و برای ادامه انگیزه بگیر.</p><div class="login-quote">«موفقیت، حاصل کارهای کوچک تکرارشده است.»</div></div>
      <div class="login-panel"><div class="eyebrow">به فضای رشدت خوش آمدی</div><h2>شروع مسیر تو 🌱</h2><p>برای دیدن اطلاعات ذخیره‌شده وارد حساب شو.</p><form @submit.prevent="login"><label v-if="authMode==='register'">نام نمایشی<input v-model="registerName" required minlength="2" autocomplete="name"/></label><label>ایمیل<input v-model="loginEmail" type="email" required autocomplete="email"/></label><label>رمز عبور<input v-model="loginPassword" type="password" required minlength="10" autocomplete="current-password"/></label><label v-if="authMode==='register'">تکرار رمز عبور<input v-model="registerPasswordConfirm" type="password" required minlength="10" autocomplete="new-password"/></label><button class="primary full" type="submit">{{authMode==='register'?'ساخت حساب کاربری':'ورود به حساب'}} <span>←</span></button></form><button class="text-btn" style="width:100%;margin-top:12px" @click="authMode=authMode==='login'?'register':'login';error=''">{{authMode==='login'?'حساب نداری؟ ثبت‌نام کن':'قبلاً حساب ساخته‌ای؟ وارد شو'}}</button><button class="secondary full demo-btn" @click="demo">مشاهده پیش‌نمایش بدون ورود</button><p class="tiny-note">حساب نمایشی پیش‌فرض: demo@habittrack.local</p><div v-if="error" class="error-msg">{{error}}</div></div>
    </section>
    <template v-else>
      <div class="page-heading"><div><div class="eyebrow">{{new Date().toLocaleDateString('fa-IR',{weekday:'long',day:'numeric',month:'long'})}}</div><h1>{{active==='داشبورد'?'سلام '+firstName+'، آماده‌ای؟ 🌿':active}}</h1><p>{{pageSubtitles[active]}}</p></div><button v-if="active==='داشبورد'||active==='عادت‌ها'" class="primary" @click="showHabitForm=true"><Plus :size="18"/> عادت جدید</button></div>
      <div v-if="error" class="notice error-msg"><CircleHelp :size="18"/>{{error}}</div>
      <div v-if="showHabitForm" class="form-card"><div class="section-head"><h3>ساخت عادت جدید</h3><button class="icon-btn" @click="showHabitForm=false"><X/></button></div><form class="inline-form" @submit.prevent="createHabit"><input v-model="habitName" placeholder="مثلاً مطالعه ۲۰ دقیقه" required/><select v-model="habitCategory"><option>رشد فردی</option><option>سلامت</option><option>یادگیری</option><option>سبک زندگی</option><option>کار</option></select><button class="primary" type="submit">ذخیره عادت</button></form></div>
      <template v-if="active==='داشبورد'">
        <div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>پیشرفت امروز</span><span class="stat-icon purple"><Activity/></span></div><div class="stat-bottom"><div class="ring" :style="{'--progress':(stats.habits?.completion_rate||0)+'%'}"><div><b>{{stats.habits?.completion_rate||0}}%</b><small>تکمیل</small></div></div><div class="stat-copy"><b>{{stats.habits?.completed||0}} از {{stats.habits?.active||habits.length}}</b><small>عادت انجام‌شده</small><em>هدف امروزت را ادامه بده</em></div></div></article>
          <article class="stat-card"><div class="stat-top"><span>زنجیره استمرار</span><span class="stat-icon orange"><Flame/></span></div><div class="number-big">{{stats.streak_days??0}} <small>روز</small></div><div class="stat-foot" :class="{positive:(stats.streak_days??0)>0}">{{(stats.streak_days??0)>0?'↗ استمرار خوب، ادامه بده':'اولین ثبت امروز، زنجیره را شروع می‌کند'}}</div></article>
          <article class="stat-card"><div class="stat-top"><span>اهداف فعال</span><span class="stat-icon cyan"><Goal/></span></div><div class="number-big">{{stats.goals?.active||goals.length}} <small>هدف</small></div><div class="mini-progress"><span :style="{width:(stats.goals?.average_progress??0)+'%'}"></span></div><div class="stat-foot">در مسیر پیشرفت</div></article>
          <article class="stat-card"><div class="stat-top"><span>زمان تمرکز</span><span class="stat-icon green"><Clock3/></span></div><div class="number-big">{{stats.focus?.minutes_today??0}} <small>دقیقه</small></div><div class="stat-foot">امروز · {{stats.focus?.sessions_today??0}} جلسه</div></article>
        </div>
        <div class="content-grid"><section class="panel habits-panel"><div class="section-head"><div><h3>عادت‌های امروز</h3><p>قدم‌های کوچکت را ثبت کن</p></div><button class="text-btn" @click="active='عادت‌ها'">مشاهده همه ←</button></div><div v-if="!filteredHabits.length" class="empty">هنوز عادتی نداری؛ اولین موردت را بساز.</div><div v-for="h in filteredHabits" :key="h.id" class="habit-row"><div class="habit-symbol" :style="{background:h.color+'22',color:h.color}"><component :is="h.icon==='book-open'?BookOpen:h.icon==='droplet'?Waves:Activity" :size="19"/></div><div class="habit-info"><b>{{h.name}}</b><small>{{h.category}} · روزانه</small></div><div class="habit-progress"><span :style="{width:doneToday(h)?'100%':'0%',background:h.color}"></span></div><span class="habit-fraction">{{doneToday(h)?'۱/۱':'۰/۱'}}</span><button class="check-btn" :class="{checked:doneToday(h)}" @click="completeHabit(h)" :title="doneToday(h)?'ثبت‌شده':'ثبت انجام عادت'"><Check :size="16"/></button></div><button class="add-habit-row" @click="showHabitForm=true"><Plus :size="17"/> افزودن عادت جدید</button></section>
        <section class="panel progress-panel"><div class="section-head"><div><h3>نمای کلی هفته</h3><p>پیشرفتت در هفت روز اخیر</p></div><button class="icon-btn" @click="active='آمار و تحلیل'"><ChartNoAxesCombined :size="17"/></button></div><div class="chart"><div v-for="day in (stats.week||[])" :key="day.date" class="chart-col"><span class="bar" :style="{height:Math.max(day.completed?10:3,Math.round(day.completed/weekMax*100))+'%'}"></span><small>{{new Date(day.date+'T12:00:00').toLocaleDateString('fa-IR',{weekday:'short'})}}</small></div></div><div class="quote-card"><Sparkles :size="18"/><div><b>پیشرفت، نه کمال‌گرایی.</b><small>یک قدم کوچک هم ارزشمند است.</small></div></div></section></div>
        <div class="bottom-grid"><section class="panel"><div class="section-head"><h3>هدف‌های تو</h3><button class="text-btn" @click="active='اهداف'">همه اهداف ←</button></div><div v-for="g in goals.slice(0,3)" :key="g.id" class="goal-row"><div class="goal-dot"><Target :size="18"/></div><div class="goal-info"><b>{{g.title}}</b><div class="mini-progress"><span :style="{width:g.progress+'%'}"></span></div></div><strong>{{g.progress}}٪</strong></div></section><section class="panel"><div class="section-head"><h3>وظایف امروز</h3><button class="text-btn" @click="active='وظایف'">مشاهده همه ←</button></div><div v-for="t in tasks.slice(0,3)" :key="t.id" class="task-row"><span class="task-check" :class="{done:t.status==='completed'}"><Check :size="13"/></span><span>{{t.title}}</span><span class="priority" :class="t.priority">{{t.priority==='high'?'بالا':t.priority==='low'?'کم':'متوسط'}}</span><button class="text-btn" @click="removeTask(t)">حذف</button></div><div v-if="!tasks.length" class="empty">وظیفه‌ای ثبت نشده است.</div></section></div>
      </template>
      <template v-else-if="active==='عادت‌ها'"><div class="toolbar"><div class="tabs"><button class="tab active">همه ({{habits.length}})</button><button class="tab">امروز</button><button class="tab">تکمیل‌شده</button></div><span class="muted">برای ثبت انجام روی دایره کنار هر عادت بزن.</span></div><section class="panel full-panel"><div v-for="h in filteredHabits" :key="h.id" class="habit-row large"><div class="habit-symbol" :style="{background:h.color+'22',color:h.color}"><Sprout/></div><div class="habit-info"><b>{{h.name}}</b><small>{{h.category}} · {{h.frequency==='daily'?'روزانه':'برنامه سفارشی'}}</small></div><div class="habit-progress"><span :style="{width:doneToday(h)?'100%':'0%',background:h.color}"></span></div><button class="check-btn" :class="{checked:doneToday(h)}" @click="completeHabit(h)"><Check/></button><button class="text-btn" @click="editHabit(h)">ویرایش</button><button class="text-btn" @click="removeHabit(h)">حذف</button></div></section></template>
      <template v-else-if="active==='تقویم'"><section class="panel calendar-panel"><div class="section-head"><div><h3>تقویم فعالیت</h3><p>روزهای انجام عادت را دنبال کن</p></div><div class="tabs"><button class="tab" @click="shiftCalendar(-1)">‹ ماه قبل</button><span class="month-label">{{calendarLabel}}</span><button class="tab" @click="shiftCalendar(1)">ماه بعد ›</button></div></div><div class="calendar-grid"><span v-for="d in ['ش','ی','د','س','چ','پ','ج']" :key="d" class="weekday">{{d}}</span><span v-for="(cell,i) in calendarCells" :key="i" class="calendar-day" :class="{today:!!cell&&cell.date===localDate(),marked:!!cell&&(calendarMarks[cell.date]||0)>0}">{{cell?cell.day:''}}</span></div><div class="legend"><span><i class="legend-dot done-dot"></i>فعالیت ثبت‌شده</span><span><i class="legend-dot"></i>بدون ثبت</span></div></section></template>
      <template v-else-if="active==='اهداف'"><div class="section-head"><div><h3>هدف‌های در حال انجام</h3><p class="muted">هر هدف را به گام‌های قابل انجام تبدیل کن.</p></div><button class="primary" @click="showGoalForm=true"><Plus/> هدف جدید</button></div><div v-if="showGoalForm" class="form-card"><form class="inline-form" @submit.prevent="createGoal"><input v-model="goalTitle" placeholder="مثلاً تکمیل نمونه‌کار تا پایان ماه" required/><select v-model="goalPriority"><option value="high">اولویت بالا</option><option value="medium">اولویت متوسط</option><option value="low">اولویت کم</option></select><button class="primary">ذخیره هدف</button><button type="button" class="secondary" @click="showGoalForm=false">انصراف</button></form></div><div v-if="!goals.length" class="panel empty">هنوز هدفی ثبت نکرده‌ای.</div><div class="goal-grid"><article v-for="g in goals" :key="g.id" class="panel goal-card"><div class="goal-card-top"><span class="goal-badge"><Target/></span><span class="priority" :class="g.priority">{{g.priority==='high'?'اولویت بالا':g.priority==='low'?'اولویت کم':'اولویت متوسط'}}</span></div><h3>{{g.title}}</h3><p class="muted">با استمرار روزانه به نتیجه نزدیک شو.</p><div class="goal-percent"><b>{{g.progress}}٪</b><span>پیشرفت</span></div><div class="mini-progress"><span :style="{width:g.progress+'%'}"></span></div><div class="goal-actions"><button class="secondary" @click="updateGoal(g,-10)">−۱۰٪</button><button class="secondary" @click="updateGoal(g,10)">+۱۰٪</button><button class="text-btn" @click="removeGoal(g)">حذف</button></div></article></div></template>
      <template v-else-if="active==='وظایف'"><section class="panel"><div class="section-head"><h3>فهرست وظایف</h3><button class="primary" @click="showTaskForm=true"><Plus/> وظیفه جدید</button></div><div v-if="showTaskForm" class="form-card"><form class="inline-form" @submit.prevent="createTask"><input v-model="taskTitle" placeholder="مثلاً ۳۰ دقیقه تمرین Laravel" required/><select v-model="taskPriority"><option value="high">اولویت بالا</option><option value="medium">اولویت متوسط</option><option value="low">اولویت کم</option></select><button class="primary">ذخیره</button><button type="button" class="secondary" @click="showTaskForm=false">انصراف</button></form></div><div v-for="t in tasks" :key="t.id" class="task-row task-large"><button class="task-check" :class="{done:t.status==='completed'}" @click="toggleTask(t)" :title="t.status==='completed'?'بازگرداندن به کارهای باز':'علامت‌گذاری به‌عنوان انجام‌شده'"><Check/></button><span :style="{textDecoration:t.status==='completed'?'line-through':'none',opacity:t.status==='completed'?.6:1}">{{t.title}}</span><span class="priority" :class="t.priority">{{t.priority==='high'?'بالا':t.priority==='low'?'کم':'متوسط'}}</span></div><div v-if="!tasks.length" class="empty">هنوز وظیفه‌ای ثبت نکرده‌ای.</div></section></template>
      <template v-else-if="active==='تایمر تمرکز'"><section class="focus-layout"><div class="panel focus-main"><div class="eyebrow">POMODORO TIMER</div><h2>زمان تمرکز تو</h2><div class="timer-ring" :style="{background:`conic-gradient(#8b7cff ${timerSeconds/(focusMinutes*60)*100}%,#26314d 0)`}"><div><b>{{String(Math.floor(timerSeconds/60)).padStart(2,'0')}}:{{String(timerSeconds%60).padStart(2,'0')}}</b><small>{{timerRunning?'در حال تمرکز':'آماده شروع'}}</small></div></div><div class="timer-controls"><button v-if="!timerRunning" class="primary" @click="startFocus">▶ شروع تمرکز</button><button v-else class="primary" @click="finishFocus">■ پایان جلسه</button><button class="secondary" @click="resetFocus">↻ بازنشانی</button></div><div class="timer-presets"><button class="tab" :class="{active:focusMinutes===25}" @click="setFocusMinutes(25)">۲۵ دقیقه</button><button class="tab" :class="{active:focusMinutes===45}" @click="setFocusMinutes(45)">۴۵ دقیقه</button><button class="tab" :class="{active:focusMinutes===60}" @click="setFocusMinutes(60)">۶۰ دقیقه</button></div><p class="muted">جلسه تمرکز در API ثبت می‌شود و با پایان، مدت واقعی ذخیره خواهد شد.</p></div><div class="panel"><h3>تنظیمات پومودورو</h3><div class="setting-line"><span>تمرکز</span><b>۲۵ دقیقه</b></div><div class="setting-line"><span>استراحت کوتاه</span><b>۵ دقیقه</b></div><div class="setting-line"><span>استراحت بلند</span><b>۱۵ دقیقه</b></div><div class="setting-line"><span>جلسات امروز</span><b>{{stats.focus?.sessions_today||0}}</b></div></div></section></template>
      <template v-else-if="active==='آمار و تحلیل'"><section class="panel"><div class="section-head"><h3>آمار مبتنی بر داده‌های حساب</h3><button class="primary" @click="loadAnalytics">به‌روزرسانی</button></div><div class="inline-form"><label>از تاریخ<input type="date" v-model="reportFrom"/></label><label>تا تاریخ<input type="date" v-model="reportTo"/></label><button class="secondary" @click="loadAnalytics">اعمال بازه</button><button class="secondary" @click="downloadCsv">خروجی CSV</button></div></section><div class="stats-grid compact"><article class="stat-card"><span>عادت فعال</span><div class="number-big">{{analytics?.habits?.length??habits.length}}</div></article><article class="stat-card"><span>نرخ تکمیل بازه</span><div class="number-big">{{analytics?.completion_rate??0}}٪</div></article><article class="stat-card"><span>ثبت تکمیل‌شده</span><div class="number-big">{{analytics?.total_completed??0}}</div></article><article class="stat-card"><span>دقیقه تمرکز</span><div class="number-big">{{analytics?.focus_minutes??0}}</div></article></div><section class="panel"><div class="section-head"><h3>روند هفت روز اخیر</h3><span class="muted">بر اساس ثبت‌های واقعی</span></div><div v-if="!analytics?.last_7_days?.length" class="empty">برای این بازه داده‌ای وجود ندارد.</div><div v-else class="chart tall"><div v-for="day in analytics.last_7_days" :key="day.date" class="chart-col"><span class="bar" :style="{height:Math.max(4,Math.min(100,day.completed*12))+'%'}"></span><small>{{new Date(day.date).toLocaleDateString('fa-IR',{weekday:'short'})}}</small></div></div><div v-for="h in analytics?.habits||[]" :key="h.id" class="setting-line"><span>{{h.name}}</span><b>{{h.completion_rate}}٪ · {{h.completed}} ثبت تکمیل</b></div></section></template>
      <template v-else-if="active==='جوایز و دستاوردها'"><section class="stats-grid compact"><article class="stat-card"><span>سطح</span><div class="number-big">{{rewardData.summary?.level||1}}</div></article><article class="stat-card"><span>امتیاز XP</span><div class="number-big">{{rewardData.summary?.xp_total||0}}</div></article><article class="stat-card"><span>پیشرفت سطح</span><div class="number-big">{{rewardData.summary?.progress_percent||0}}٪</div></article></section><section class="panel"><h3>نشان‌های کسب‌شده</h3><div v-if="!rewardData.badges?.length" class="empty">هنوز نشانی ثبت نشده است. با ثبت فعالیت‌های واقعی، قوانین اعطای نشان باید اعمال شوند.</div><div v-for="b in rewardData.badges||[]" :key="b.id" class="setting-line"><b>{{b.title||b.name||b.badge_key}}</b><span>{{b.earned_at||''}}</span></div><h3 style="margin-top:22px">تاریخچه XP</h3><div v-for="e in rewardData.events||[]" :key="e.id" class="setting-line"><span>{{e.event_type}}</span><b>+{{e.xp}} XP</b></div></section></template>
      <template v-else-if="active==='مربی هوشمند'"><section class="panel coach-panel"><div class="coach-avatar"><Sparkles :size="35"/></div><div><div class="eyebrow">HABIT COACH · RULE-BASED</div><h2>پیشنهادهای مبتنی بر تاریخچه واقعی</h2><p class="muted">عادت‌های تحلیل‌شده: {{coachSummary.habits_analyzed||0}} · بازه: {{coachSummary.window_days||28}} روز</p></div><div v-if="!coachItems.length" class="empty">هنوز پیشنهاد قابل اتکایی تولید نشده است. چند روز فعالیت ثبت کن و دوباره بررسی کن.</div><article v-for="item in coachItems" :key="item.id" class="coach-tip"><b>{{item.title}}</b><p>{{item.reason}}</p><small>وضعیت: {{item.status}}</small><div v-if="item.status==='pending'" class="goal-actions"><button class="primary" @click="decideCoach(item,'accepted')">می‌پذیرم</button><button class="secondary" @click="decideCoach(item,'rejected')">رد پیشنهاد</button></div><button v-else-if="item.status==='accepted'||item.status==='rejected'" class="secondary" @click="evaluateCoach(item)">ثبت ارزیابی نتیجه</button></article></section></template>
      <template v-else-if="active==='اعلان‌ها'"><section class="panel"><div class="section-head"><h3>مرکز اعلان‌ها</h3><button class="secondary" @click="markAllNotificationsRead">خوانده‌شدن همه</button></div><div v-if="!notifications.length" class="empty">اعلانی در حساب شما ثبت نشده است.</div><article v-for="n in notifications" :key="n.id" class="setting-line"><div><b>{{n.title||n.type||'اعلان HabitTrack'}}</b><p class="muted">{{n.body||n.message||''}}</p><small>{{n.created_at?new Date(n.created_at).toLocaleString('fa-IR'):''}}</small></div><button v-if="!n.read_at" class="secondary" @click="markNotificationRead(n)">خوانده شد</button><span v-else class="pill-status">خوانده‌شده</span></article><p class="muted">این صفحه اعلان‌های ذخیره‌شده در API را نشان می‌دهد؛ ارسال خودکار نیازمند تنظیم Scheduler/Queue در سرور است.</p></section></template>
      <template v-else-if="active==='پروفایل'"><section class="panel profile-card"><div class="avatar huge">{{displayInitial}}</div><h2>{{displayName}}</h2><p class="muted">{{isDemo?'حالت نمایشی':currentUser?.email||''}}</p><div class="stats-grid compact"><div class="stat-card"><span>عادت‌ها</span><b class="number-big">{{habits.length}}</b></div><div class="stat-card"><span>هدف‌ها</span><b class="number-big">{{goals.length}}</b></div><div class="stat-card"><span>وظایف</span><b class="number-big">{{tasks.length}}</b></div></div></section></template>
      <template v-else-if="active==='تنظیمات'"><section class="panel"><h3>تنظیمات ذخیره‌شونده حساب</h3><form @submit.prevent="saveSettings"><div class="setting-line"><label>تم رابط</label><select v-model="settings.theme"><option value="dark">تاریک</option><option value="light">روشن</option><option value="system">مطابق سیستم</option></select></div><div class="setting-line"><label>رنگ تأکیدی</label><input v-model="settings.accent_color" type="color"/></div><h3>ترجیحات اعلان</h3><p class="muted">فعلاً فقط ذخیره می‌شوند؛ ارسال خودکار اعلان هنوز فعال نیست.</p><div v-for="pref in [{key:'habit_reminders',label:'یادآوری عادت‌ها'},{key:'daily_summary',label:'خلاصه روزانه'},{key:'weekly_summary',label:'خلاصه هفتگی'},{key:'task_deadlines',label:'مهلت وظایف'}]" :key="pref.key" class="setting-line"><span>{{pref.label}}</span><input v-model="settings.notification_preferences[pref.key]" type="checkbox"/></div><button class="primary" type="submit" :disabled="settingsSaving">{{settingsSaving?'در حال ذخیره…':'ذخیره تنظیمات'}}</button></form></section></template>
      <template v-else-if="active==='پشتیبان‌گیری'"><section class="panel backup-panel"><div class="backup-icon"><ShieldCheck :size="35"/></div><h2>اطلاعاتت دست خودت است.</h2><p class="muted">نسخه پشتیبان کامل از سرور شامل عادت‌ها، ثبت‌ها، اهداف، وظایف، جلسات تمرکز و تنظیمات دریافت می‌شود.</p><button class="primary" @click="downloadBackup">↓ دریافت نسخه پشتیبان JSON</button></section></template>
    </template>
    <footer class="footer"><span>© 2026 HabitTrack</span><span><Waves :size="14"/> قدم‌های کوچک، آینده روشن</span><span>ساخته‌شده برای رشد روزانه</span></footer>
  </main>
  <Transition><div v-if="toast" class="toast"><Check :size="17"/>{{toast}}</div></Transition>
</div>
</template>
